// def scalar_twin(b: Box, q: Box) -> None:
//     a = b
//     a.n = 23
//     a = q  # tpyc: ok
//     a.n = 24
//     print("scalar_twin", b.n, q.n)
void scalar_twin(Box& b, Box& q) {
    Box* a = &(b);
    a->n = 23;
    a = &(q);
    a->n = 24;
    std::cout << "scalar_twin" << " " << b.n << " " << q.n << "\n" << ::tpy::check_signals;
}

